class ChampFiche(BaseModel):
    nom: Annotated[str, Field(pattern='^[a-z][a-z0-9_]{0,63}$', title='Nom')]
    """
    snake_case name of the field, also the tool parameter name.
    """
    type: Annotated[Type | None, Field(title='Type')] = 'string'
    origine: OrigineChamp | None = 'dicte'
    """
    Dictated: the value must have been said by the caller (name, town, street, number, brand). Deduced: the model sums it up (reason, urgency).
    """
    description: Annotated[str | None, Field(max_length=500, title='Description')] = ''
    """
    Hint given to the model for this parameter.
    """
    lecteur: Annotated[Lecteur | None, Field(title='Lecteur')] = None
    """
    Which reader checks the value: town (official name and INSEE code), street (official street name), date (a relative date such as 'last year' computed on the day of the call, the caller's words kept), trade vocabulary (a name of the organization's vocabulary, sure only when recognised), or none. Empty: from the field name.
    """
    valeurs: Annotated[list[str] | None, Field(title='Valeurs')] = None
    """
    Allowed values: the field only accepts one of them (case and accents ignored), written as declared. Empty: any value.
    """
    cumulatif: Annotated[bool | None, Field(title='Cumulatif')] = False
    """
    Cumulative: each note is added to what the field already holds, nothing is overwritten; not checked against the caller's exact words.
    """
    copie_de_la_parole: Annotated[bool | None, Field(title='Copie De La Parole')] = (
        False
    )
    """
    Copied from the caller's words: when the model notes this field, the code writes the caller's exact words of that reply; the model only writes '='. Saves the model copying a whole sentence.
    """
    chiffres: Annotated[Chiffres | None, Field(title='Chiffres')] = None
    """
    Digits: how many digits the value must hold (spaces and signs ignored); a value with more or fewer is refused and the caller is asked for it again in full. Empty: no check.
    """
    rempli_en_fin_d_appel: Annotated[
        bool | None, Field(title='Rempli En Fin D Appel')
    ] = True
    """
    Filled at the end of the call: if the agent did not note the field during the call, the end-of-call pass may fill it from the conversation. Off: only the agent writes it, while the caller is speaking.
    """
    portee: Annotated[Portee | None, Field(title='Portee')] = None
    """
    Scope in a call with several requests: whole call (what concerns the caller: shared by every request) or this request (closed with it when another specialist takes over). Empty: computed from the agent's settings (town and street readers, field recognition).
    """


class ContextDestinationMappingConfig(BaseModel):
    """
    Resolve a transfer destination from gathered or initial context.

    Rules are evaluated in order. The first rule whose context value matches
    one of its routes wins; ``fallback_destination`` applies only when no rule
    matched. Destinations may be provider-native values or context templates.
    """

    rules: Annotated[list[ContextDestinationRule] | None, Field(title='Rules')] = None
    """
    Ordered routing rules evaluated top to bottom; first match wins.
    """
    context_path: Annotated[str | None, Field(title='Context Path')] = None
    """
    Deprecated single-rule context path. Use rules instead; accepted for backward compatibility.
    """
    routes: Annotated[list[ContextDestinationRoute] | None, Field(title='Routes')] = (
        None
    )
    """
    Deprecated single-rule routes. Use rules instead; accepted for backward compatibility.
    """
    fallback_destination: Annotated[
        FallbackDestination | None, Field(title='Fallback Destination')
    ] = None
    """
    Optional provider-native destination or context template used when no rule matched.
    """


